  refresh: 'M13 8a5 5 0 1 1-2-4.6 M13.5 2.6v3h-3',
  back: 'M10 3.5L5.5 8l4.5 4.5',
  up: 'M4 10l4-4 4 4',
  down: 'M4 6l4 4 4-4',
  send: 'M2.8 8L14 2.8 8.6 14l-1.7-4.6z',
